hyp=['Finite independent uniform sign blocks W,S,X,Y; only S may occur in both branches','Branches and controller sign Boolean, with arbitrary output means; entropy in bits','Seed references normalized and positive on true support; every shared-only atom calibrated; remaining terminal conditional debt retained','No arbitrary-event conditioning; restriction claims concern actual uniform subcubes','Profile norm hypotheses required only for the stated constant admission; no all-dimensional absolute collision price or reset telescope']
c={'claim_id':'A056-TWO-BRANCH-COMMON-CONTROL-TRANSPORT','version':2,'exact_statement':statement,'hypotheses':hyp,'statement_sha256':digest(json.dumps({'statement':statement,'hypotheses':hyp},sort_keys=True,separators=(',',':')).encode()),'contributors':['fleet05/A056'],'proof_source':{'path':str(R/'DERIVATION.md'),'retained_v1':str(HOME/'runs/20261013T215801Z-fleet05-A056-balanced-composition/PROOF.md')},'proof_dependencies':[{'claim_id':'A056-TWO-BRANCH-COMMON-CONTROL-TRANSPORT','version':1,'role':'retained disjoint and priority assertions only; new scalar and reference formulas proved directly'}],'review_records':[],'status':'PROVED_LOCALLY_PENDING_INDEPENDENT_REVIEW','supersedes':[{'claim_id':'A056-TWO-BRANCH-COMMON-CONTROL-TRANSPORT','version':1}],'refutes':[],'first_unproved_line':None,'next_consumers':['A057','A058','A059','A091','A090','A097','A094','A013','A095','B20']}
