sources=[BASE/'BOARD.md',BASE/'claude/B12/STREAM_NOTES.md',BASE/'agents/A097/runs/20261013T222610Z-fleet05-A097-cross-route-transfer/DERIVATION.md',BASE/'agents/A091/runs/20261013T220323Z-fleet05-A091-composition-referee/REPORT.md',source/'code/save.py',source/'CLAIMS.json',BASE/'agents/A095/runs/20261013T213857Z-fleet05-A095-restricted-result-extraction/REPORT.md',HOME/'runs/20261013T215801Z-fleet05-A056-balanced-composition/CLAIMS.json',HOME/'runs/20261013T215801Z-fleet05-A056-balanced-composition/code/check.py']
